import { MakeLogicType, afterMount, connect, kea, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { platformAlertsList } from '../generated/api'
import type { PlatformAlertConfigurationApi } from '../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface platformAlertsLogicValues {
    currentTeamId: number | null // teamLogic
    platformAlerts: PlatformAlertConfigurationApi[] | null
    platformAlertsLoading: boolean
    platformAlertsLoadFailed: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface platformAlertsLogicActions {
    loadPlatformAlerts: (_?: any) => any
    loadPlatformAlertsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadPlatformAlertsSuccess: (
        platformAlerts: PlatformAlertConfigurationApi[] | null,
        payload?: any
    ) => {
        platformAlerts: PlatformAlertConfigurationApi[] | null
        payload?: any
    }
}

export type platformAlertsLogicType = MakeLogicType<platformAlertsLogicValues, platformAlertsLogicActions>

export const platformAlertsLogic = kea<platformAlertsLogicType>([
    path(['products', 'alerts', 'frontend', 'logic', 'platformAlertsLogic']),

    connect({
        values: [teamLogic, ['currentTeamId']],
    }),

    loaders(({ values }) => ({
        platformAlerts: [
            null as PlatformAlertConfigurationApi[] | null,
            {
                loadPlatformAlerts: async (_ = null, breakpoint) => {
                    const response = await platformAlertsList(String(values.currentTeamId), { limit: 500 })
                    breakpoint()
                    return response.results
                },
            },
        ],
    })),

    reducers({
        platformAlertsLoadFailed: [
            false,
            {
                loadPlatformAlerts: () => false,
                loadPlatformAlertsSuccess: () => false,
                loadPlatformAlertsFailure: () => true,
            },
        ],
    }),

    afterMount(({ actions }) => {
        actions.loadPlatformAlerts()
    }),
])
